// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Transfer ownership to the fuzzed actor.
        vm.prank(address(this));
        c.setOwner(actor);

        // Rule: the newly-set owner must retain owner privileges and be able
        // to call setOwner again successfully.
        vm.prank(actor);
        bool ok;
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
